<script lang="ts">
 import type { Transform, Reply, AssetRecord, ExpressionSettings } from '@opensekai/contracts';
 import type {AssetLoadStatus} from '@opensekai/renderer';
 import {modelLabel} from '../editor/authoring';
 import AvatarModelField from './AvatarModelField.svelte';
 import AvatarExpressionFields,{type ExpressionApi} from './AvatarExpressionFields.svelte';
 import {hasTriggerableExpressions} from '../editor/expressions';
 import type { EditorPanelProps } from '../editor/model';
 import {antiAliasingOptions,matchingStatus,type LivePropertyCallbacks} from '../editor/live-fields';
 import { Select } from '@oshi-connect/ui';
 import { CameraAntiAliasingSchema } from '@opensekai/contracts';
 import CameraLensFields from './CameraLensFields.svelte';
 import CameraNavigationFields from './CameraNavigationFields.svelte';
 import { Button } from '@oshi-connect/ui';
 import type { CameraNavigation, CameraScreenshotResult } from '@opensekai/contracts';
 import EnvironmentFields from './EnvironmentFields.svelte';
 import AvatarSourceFields from './AvatarSourceFields.svelte';
 import TrackingAdvanced from './TrackingAdvanced.svelte';
 import TrackingSourceFields from './TrackingSourceFields.svelte';
 import TransformFields from './TransformFields.svelte';
 type Props=LivePropertyCallbacks&Omit<EditorPanelProps,'model'>&{model:EditorPanelProps['model']&{setTransform?:(id:string,transform:Transform,revision?:number)=>Promise<Reply<{revision:number}>>};draft?:{entityId:string;transform:Transform}|null;ondraft?:(draft:{entityId:string;transform:Transform}|null)=>void;disabled?:boolean;onlivetransform?:(id:string,transform:Transform)=>void;oncanceltransform?:()=>void;onfinishtransform?:()=>void;transformError?:string|null;livePending?:boolean;assets?:AssetRecord[];loads?:AssetLoadStatus[];importingId?:string|null;onchoosemodel?:(id:string)=>void;importError?:{entityId:string;message:string}|null;onchoosescene?:(id:string)=>void;onpickscene?:(id:string,assetId:string|null)=>void;onrenderenvironment?:(id:string,value:boolean,revision:number)=>Promise<Reply<unknown>|undefined>;expressionApi?:ExpressionApi|null;onexpressionsettings?:(id:string,name:string,settings:ExpressionSettings|null,revision:number)=>Promise<unknown>;onnavigation?:(id:string,navigation:CameraNavigation,revision:number)=>Promise<Reply<unknown>|undefined>;onscreenshot?:(id:string)=>Promise<Reply<CameraScreenshotResult>|undefined>;onopenscreenshots?:()=>Promise<void>};
 let {model,view,draft=null,ondraft,disabled=false,onlivetransform,oncanceltransform,onfinishtransform,transformError=null,livePending=false,assets=[],loads=[],importingId=null,importError=null,onchoosemodel,onchoosescene,onpickscene,onrenderenvironment,expressionApi=null,onexpressionsettings,onnavigation,onscreenshot,onopenscreenshots,onlens,onavatartracking,onavataridle,ontrackingconfig,ontrackingsmoothing,ontrackingtoggle,trackingStatus=[],devices=[]}:Props=$props();
 const entity=$derived(view.scene?.entities.find(item=>item.id===view.selectedId));
 // A rejected change leaves the scene value as it was, so Svelte does not reset the box; put the scene value back.
 const settle=(box:HTMLInputElement,reply:Reply<unknown>|undefined,current:boolean|undefined)=>{if(!reply?.ok&&current!==undefined)box.checked=current;};
 let shooting=$state(false),shot=$state<{entityId:string;fileName:string}|null>(null),shotError=$state<string|null>(null);
 async function screenshot(id:string){shooting=true;shotError=null;try{const reply=await onscreenshot?.(id);if(reply?.ok)shot={entityId:id,fileName:reply.data.fileName};else if(reply)shotError=reply.error.code;}finally{shooting=false;}}
 async function openFolder(){shotError=null;try{await onopenscreenshots?.();}catch{shotError='Could not open folder';}}
</script>
<section class="editor-panel inspector" aria-labelledby="inspector-heading">
 <h2 id="inspector-heading">Properties</h2>
 {#if entity && view.scene}<h3>{entity.name}</h3>{#if entity.kind!=='tracking'}<label class="visibility-control"><input type="checkbox" checked={entity.visible} disabled={view.pending||disabled} onchange={async event=>{const box=event.currentTarget;const reply=await model.setVisibility(entity.id,box.checked,view.scene?.revision);settle(box,reply,entity?.visible);}}/>Visible</label>
 <TransformFields entityId={entity.id} baseTransform={entity.transform} transform={draft?.entityId===entity.id?draft.transform:entity.transform} revision={view.scene.revision} disabled={disabled||(view.pending&&!view.transformPending)} committing={livePending||(view.transformPending??false)} cancelKey={transformError??view.error} oncommit={(transform,revision)=>{if(onlivetransform)onlivetransform(entity.id,transform);else void model.setTransform?.(entity.id,transform,revision);}} oncancel={oncanceltransform} onfinish={onfinishtransform}/>
 {/if}
 {#if entity.kind==='camera'}<label class="visibility-control"><input type="checkbox" checked={entity.renderEnvironment!==false} disabled={view.pending||disabled||!onrenderenvironment} onchange={async event=>{const box=event.currentTarget;const reply=await onrenderenvironment?.(entity.id,box.checked,view.scene!.revision);settle(box,reply,entity?.kind==='camera'?entity.renderEnvironment!==false:undefined);}}/>Render Environment</label><Select label="Anti-aliasing" value={entity.antiAliasing??'none'} options={antiAliasingOptions} disabled={view.pending||disabled} onchange={async event=>{const select=event.currentTarget;const mode=CameraAntiAliasingSchema.safeParse(select.value);const reply=mode.success?await model.setCameraAntiAliasing(entity.id,mode.data,view.scene?.revision):undefined;if(!reply?.ok&&entity?.kind==='camera')select.value=entity.antiAliasing??'none';}}/><CameraLensFields entityId={entity.id} lens={entity.lens} revision={view.scene.revision} disabled={view.pending||disabled} oncommit={onlens}/><CameraNavigationFields entityId={entity.id} navigation={entity.navigation} entities={view.scene.entities} revision={view.scene.revision} disabled={view.pending||disabled} oncommit={onnavigation}/><div class="screenshot-actions"><Button variant="secondary" disabled={shooting||disabled||!onscreenshot} onclick={()=>screenshot(entity!.id)}>Take Screenshot</Button><Button variant="ghost" disabled={!onopenscreenshots} onclick={openFolder}>Open Screenshots Folder</Button></div>{#if shot?.entityId===entity.id}<p class="screenshot-file">{shot.fileName}</p>{/if}{#if shotError}<p role="alert">{shotError}</p>{/if}{:else if entity.kind==='environment'}<EnvironmentFields assetId={entity.assetId} {assets} status={loads.find(load=>load.entityId===entity.id)??null} importing={importingId===entity.id} error={importError?.entityId===entity.id?importError.message:null} disabled={view.pending||livePending||disabled||!onchoosescene} onselect={assetId=>onpickscene?.(entity.id,assetId)} onimport={()=>onchoosescene?.(entity.id)}/>{:else if entity.kind==='avatar'}<AvatarModelField label={modelLabel(entity.assetId,assets)} status={loads.find(load=>load.entityId===entity.id)??null} importing={importingId===entity.id} disabled={view.pending||livePending||disabled||!onchoosemodel} onchoose={()=>onchoosemodel?.(entity.id)}/>{#if expressionApi&&onexpressionsettings&&hasTriggerableExpressions(entity.assetId,assets)}<AvatarExpressionFields avatarId={entity.id} revision={view.scene.revision} api={expressionApi} disabled={view.pending||livePending||disabled} onsettings={onexpressionsettings}/>{/if}<AvatarSourceFields entityId={entity.id} tracking={entity.tracking} idleAnimation={entity.idleAnimation} onidle={onavataridle} entities={view.scene.entities} revision={view.scene.revision} disabled={view.pending||livePending||disabled} oncommit={onavatartracking}/>{:else if entity.kind==='tracking'}<TrackingSourceFields entityId={entity.id} config={entity.config} generation={entity.generation} revision={view.scene.revision} disabled={view.pending||disabled} oncommit={ontrackingconfig} ontoggle={ontrackingtoggle} statuses={trackingStatus} {devices}/><TrackingAdvanced entityId={entity.id} kind={entity.config.kind} smoothing={entity.smoothing} generation={entity.generation} status={matchingStatus(trackingStatus,entity.id,entity.generation)} revision={view.scene.revision} disabled={view.pending||disabled} oncommit={ontrackingsmoothing}/>{/if}
 {/if}
 {#if view.error}<p role="alert">{view.error==='CONFLICT'?'Scene changed. Review values and retry.':view.error}</p>{/if}
</section>
<style>.screenshot-actions{display:flex;flex-wrap:wrap;gap:8px;padding-top:12px}.screenshot-file{margin:6px 0 0;font-size:12px;color:#6b6575;overflow-wrap:anywhere}</style>
